const e=$json.execution||{};
const w=$json.workflow||{};
const message=String(e.error?.message||$json.error?.message||'');
let error_code='WORKFLOW_ERROR';
if(/MCP.*(connect|unavailable|refused)/i.test(message)) error_code='MCP_CONNECTION_ERROR';
else if(/MCP.*timeout|timeout.*MCP/i.test(message)) error_code='MCP_TIMEOUT';
else if(/openai|model|llm/i.test(message)) error_code='OPENAI_ERROR';
else if(/validation/i.test(message)) error_code='VALIDATION_ERROR';
else if(/denied|unauthor|forbidden|permission/i.test(message)) error_code='APPROVAL_DENIED';
else if(/expired/i.test(message)) error_code='EXPIRED_PROPOSAL';
else if(/stale|version|conflict/i.test(message)) error_code='STALE_PROPOSAL';
else if(/sqlite|database|storage/i.test(message)) error_code='DATABASE_ERROR';
const execution_id=String(e.id||$execution.id||'unknown').replace(/[^A-Za-z0-9._:-]/g,'_').slice(0,200);
const workflow_id=w.id?String(w.id).replace(/[^A-Za-z0-9._:-]/g,'_').slice(0,200):null;
const correlation_id=$json.correlation_id?String($json.correlation_id).replace(/[^A-Za-z0-9._:-]/g,'_').slice(0,200):null;
return [{json:{occurred_at:new Date().toISOString(),workflow_id,execution_id,correlation_id,error_code,status:'FAILED'}}];
